export const state={isAdmin:!1,role:"child",balance:0,tasks:[],shopItems:[],history:[],requests:[],friends:[],childNickname:null,isPinSet:!1,familyId:null,monthlyLimit:1e4,dailyCoinLimit:0,baseData:{tasks:[],products:[]},children:[],currentChildId:null,isLoading:!0};const listeners=[];export function subscribe(t){listeners.push(t)}export function notify(){listeners.forEach(t=>t(state))}export function setState(t){Object.assign(state,t),notify()}export function updateBalance(t){state.balance+=t,notify()}